package com.nivor.ai;import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;
@Entity @Table(name="ai_memories",indexes=@Index(name="idx_ai_memory_user",columnList="user_id,created_at"))public class AiMemory extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Column(nullable=false,length=60)private String category;@Column(nullable=false,length=2000)private String content;@Column(nullable=false)private int importance;protected AiMemory(){}public User getUser(){return user;}public void setUser(User v){user=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public int getImportance(){return importance;}public void setImportance(int v){importance=v;}}
